#![cfg_attr(verus_keep_ghost, verifier::exec_allows_no_decreases_clause)]
#![allow(unused_imports)]

use verus_builtin::*;
use verus_builtin_macros::*;
use vstd::atomic_ghost::*;
use vstd::cell::pcell_maybe_uninit::*;
use vstd::prelude::*;
use vstd::*;
use vstd::raw_ptr::MemContents;

use std::sync::atomic::*;

verus! {

// A simple counter, albeit with nothing verified about it.
exec static GLOBAL_COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

fn increment_counter() {
    GLOBAL_COUNTER.fetch_add(1, Ordering::Relaxed);
}

// Thread-safe lazy initialization
pub tracked enum GhostState<T: 'static> {
    Uninitialized(PointsTo<Option<T>>),
    Initializing,
    Initialized(&'static PointsTo<Option<T>>),
}

struct_with_invariants!{
    struct Lazy<T: 'static> {
        pub cell: PCell<Option<T>>,
        pub state: vstd::atomic_ghost::AtomicU64<_, GhostState<T>, _>
    }

    spec fn wf(&self) -> bool {
        invariant on state with (cell) is (v: u64, g: GhostState<T>) {
            // State = 0: Uninitialized
            // State = 1: currently initializing
            // State = 2: is initialized
            match g {
                GhostState::Uninitialized(points_to) => {
                    v == 0
                      && points_to.id() == cell.id()
                      && (points_to.mem_contents() == MemContents::Init(None))
                }
                GhostState::Initializing => {
                    v == 1
                }
                GhostState::Initialized(points_to) => {
                    v == 2
                      && points_to.id() == cell.id()
                      && (points_to.mem_contents() matches MemContents::Init(Some(_)))
                }
            }
        }
    }
}

trait Initializable: Sized {
    fn initialize() -> Self;
}

impl<T: Initializable> Lazy<T> {
    const fn new() -> (s: Self)
        ensures
            s.wf(),
    {
        let (pcell, Tracked(points_to)) = PCell::new(None);
        Lazy {
            cell: pcell,
            state: vstd::atomic_ghost::AtomicU64::new(
                Ghost(pcell),
                0,
                Tracked(GhostState::Uninitialized(points_to)),
            ),
        }
    }

    fn get<'a>(&'a self) -> &'a T
        requires
            self.wf(),
    {
        loop
            invariant
                self.wf(),
        {
            let tracked mut readonly_points_to: Option<&'static PointsTo<Option<T>>> = None;
            let cur_state =
                atomic_with_ghost!(&self.state => load(); ghost g => {
                    match g {
                        GhostState::Uninitialized(points_to) => {
                            // State = 0
                            // We can't borrow yet, but we might be able to initialize
                            readonly_points_to = None;
                        }
                        GhostState::Initializing => {
                            // State = 1
                            // Someone else is initializing, wait for them
                            readonly_points_to = None;
                        }
                        GhostState::Initialized(points_to) => {
                            // State = 2
                            // Already initialized, we can borrow
                            readonly_points_to = Some(points_to);
                        }
                    }
                });
            if cur_state == 2 {
                // Already initialized.
                // At this point, readonly_points_to should be Some(points_to)
                // But we need to prove it
                assert(readonly_points_to.is_Some());
                return self.cell.borrow(
                    Tracked(readonly_points_to.tracked_borrow()),
                ).as_ref().unwrap();
            } else {
                // Initialization is required. Try to take the lock if initialization
                // isn't already in progress.
                let mut do_initialization = (cur_state == 0);
                let tracked mut points_to: Option<PointsTo<Option<T>>> = None;
                if do_initialization {
                    let res =
                        atomic_with_ghost!(&self.state => compare_exchange(0, 1);
                        returning res; ghost g =>
                    {
                        match g {
                            GhostState::Uninitialized(points_to_arg) => {
                                // We're trying to transition from Uninitialized to Initializing
                                // But compare_exchange succeeded, so we should have successfully
                                // changed the state to Initializing
                                // 
                                // Wait, the ghost state after compare_exchange should reflect
                                // the new state (Initializing)
                                // But the ghost block is called with the OLD ghost state
                                // So we should be in GhostState::Uninitialized here
                                points_to = Some(points_to_arg);
                            }
                            GhostState::Initializing => {
                                // State was already Initializing (race)
                                // No points_to to extract
                                points_to = None;
                            }
                            GhostState::Initialized(points_to_arg) => {
                                // State was already Initialized (race)
                                // No points_to to extract
                                points_to = None;
                            }
                        }
                    });
                    if res.is_err() {
                        // don't initialize after all
                        do_initialization = false;
                    }
                }
                if do_initialization {
                    // At this point, we should have points_to from the invariant
                    assert(points_to.is_Some());
                    // Do initialization
                    let t = T::initialize();
                    let tracked mut points_to = points_to.tracked_unwrap();
                    self.cell.replace(Tracked(&mut points_to), Some(t));
                    let tracked static_points_to = vstd::modes::tracked_static_ref(points_to);
                    atomic_with_ghost!(&self.state => store(2); ghost g => {
                        match g {
                            GhostState::Initializing => {
                                // We're transitioning from Initializing to Initialized
                                // The ghost state before was Initializing (no data)
                                // After the store, the invariant should hold with the new state
                                // We need to provide the new ghost state
                                // But the ghost block only gets to modify g, not return it
                                // The invariant must hold after the atomic operation
                                // So we just need to ensure the invariant holds
                                // Since we're storing 2, the invariant says g should be
                                // GhostState::Initialized(static_points_to)
                                // But we're not changing g in the block
                                // So we need to set g to the right value
                                // Actually, looking at the macro, g is passed in and out
                            }
                            _ => {}
                        }
                        g = GhostState::Initialized(static_points_to);
                    });
                    return self.cell.borrow(Tracked(static_points_to)).as_ref().unwrap();
                } else {
                    // Wait for initialization to complete by a different thread
                    // (Try again in the next iteration of the loop.)
                }
            }
        }
    }
}

// Example usage
struct X {}

impl Initializable for X {
    fn initialize() -> Self {
        X {  }
    }
}

exec static LAZY_X: Lazy<X>
    ensures
        LAZY_X.wf(),
{
    Lazy::<X>::new()
}

fn get_lazy_x() -> &'static X {
    LAZY_X.get()
}

fn main() {
}

} // verus!

