verus! {

struct X {}

fn get_tracked() -> (res: Tracked<X>) {
    let tracked mut x_opt: Option<X> = None;

    proof {
        x_opt = Some(X {});
    }

    // Use x_opt in exec context
    let tracked x = match x_opt {
        Option::Some(t) => t,
        Option::None => proof_from_false(),
    };

    // Wrap x in Tracked
    Tracked(x)
}

fn main() {}

} // verus!

